# --- Population data ---
pop_raw &lt;- read_excel(file.path(PROJE, "tr_nufus.xlsx"))
colnames(pop_raw) &lt;- c("year", "province", "total", "male", "female")

pop &lt;- pop_raw |&gt;
  mutate(year = as.integer(year)) |&gt;
  arrange(province, year) |&gt;
  group_by(province) |&gt;
  mutate(
    pop_change     = total - lag(total),
    pop_change_pct = pop_change / lag(total) * 100,
    sex_ratio      = male / female * 100,
    period = case_when(
      year &lt;= 2022 ~ "Pre-Earthquake",
      year == 2023 ~ "Earthquake Year",
      TRUE         ~ "Recovery"
    ) |&gt; factor(levels = c("Pre-Earthquake",
                            "Earthquake Year",
                            "Recovery"))
  ) |&gt;
  ungroup()

# --- Migration flow data ---
mig_raw &lt;- read_excel(file.path(PROJE, "deprem_goc_ham_filtreli.xlsx"),
                      skip = 2)
colnames(mig_raw) &lt;- c("year", "dest", "origin",
                        "dest_pop", "origin_pop",
                        "in_mig", "out_mig", "net_mig")
mig &lt;- mig_raw |&gt;
  filter(!is.na(year)) |&gt;
  mutate(year = as.integer(year))

# Net migration per province per year
net_mig_prov &lt;- mig |&gt;
  group_by(year, province = dest) |&gt;
  summarise(net_mig = sum(net_mig, na.rm = TRUE), .groups = "drop")

# --- ADNKS growth rates ---
adnks_raw &lt;- read_excel(file.path(PROJE, "adnks_il.xls"),
                         col_names = FALSE, skip = 3)
adnks &lt;- adnks_raw |&gt;
  select(province = 1, pop_2022 = 2, pop_2023 = 3,
         rate_2122 = 11, rate_2223 = 12) |&gt;
  filter(!is.na(province), province != "Toplam-Total") |&gt;
  mutate(across(c(pop_2022, pop_2023, rate_2122, rate_2223), as.numeric))

# --- GDP contribution data ---
gsyh_raw &lt;- read_excel(file.path(PROJE, "gsyh_il_2020_2024.xls"),
                        skip = 4, col_names = FALSE)
colnames(gsyh_raw) &lt;- c("code", "prov_raw",
                         "y2020", "y2021", "y2022", "y2023", "y2024")

gdp &lt;- gsyh_raw |&gt;
  filter(code %in% names(NUTS3_CODES)) |&gt;
  mutate(province = NUTS3_CODES[code]) |&gt;
  select(province, y2020:y2024) |&gt;
  mutate(across(y2020:y2024, as.numeric)) |&gt;
  pivot_longer(y2020:y2024,
               names_to  = "year",
               values_to = "gdp_contrib") |&gt;
  mutate(year = as.integer(str_remove(year, "y")))

# --- Combined panel ---
panel &lt;- pop |&gt;
  left_join(net_mig_prov, by = c("year", "province")) |&gt;
  mutate(mig_rate = net_mig / total * 1000)

# Save RData
save(pop, mig, panel, gdp, adnks, net_mig_prov,
     file = file.path(PROJE, "deprem_goc_analizi.RData"))

